    assert.match(lines[1], /ACME Corporation/);
  });

  await t.test('quotes field with comma in customer name', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'XYZ',
        issueDate: '2026-10-01',
        dueDate: '2026-10-31',
