      {
        number: 'INV-001',
        customerId: 'ACME',
        issueDate: '2026-10-01',
        dueDate: '2026-10-31',
        status: 'issued',
        lines: [
          { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 20 },
          { qty: 50, unitPrice: 1000, discountPercent: 10, vatRate: 20 },
        ],
      },
    ];
    const result = exportCsv(invoices);
    const lines = result.split('\n');
    // subtotal = 50*1000 + 50*1000 = 100000
    // discount = 0 + 50*1000*0.1 = 5000
    // vat = 50*1000*0.2 + (50*1000-5000)*0.2 = 10000 + 9000 = 19000
    // total = 100000 - 5000 + 19000 = 114000
    assert.match(lines[1], /100000\.00.*5000\.00.*19000\.00.*114000\.00/);
  });

  await t.test('can be parsed back as CSV', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'ACME',
        issueDate: '2026-10-01',
        dueDate: '2026-10-31',
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
